<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ArrowDown, ArrowUp, Check, Plus, Save, ShoppingCart, Trash2, X } from 'lucide-vue-next'
import JalaliDatePicker from '../components/JalaliDatePicker.vue'
import SectionPanel from '../components/SectionPanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue'
import SelectField from '../components/SelectField.vue'
import { purchasesApi, type PurchasePayload, type PurchaseRecord } from '../api/purchases'
import type { SupplierRecord } from '../api/suppliers'
import type { MaterialRecord } from '../api/materials'
import { formatMoney, type CurrencyUnit } from '../utils/currency'
import { currentCanonicalDate, formatDateTime } from '../utils/date'
import { confirmAction, normalizeError } from '../ui/feedback'

const props = defineProps<{ currencyUnit: CurrencyUnit; suppliers: SupplierRecord[]; materials: MaterialRecord[] }>()
const emit = defineEmits<{ notify: [string] }>()
const rows = ref<PurchaseRecord[]>([])
const selectedId = ref<string | null>(null)
const loading = ref(false)
const error = ref('')
const editing = ref(false)
const form = ref<PurchasePayload>(blank())
const item = ref({ materialId: '', purchaseQuantity: '1', unitAcquisitionCostRial: '0', notes: '' })
const current = computed(() => rows.value.find((value) => value.id === selectedId.value) ?? null)

function blank(): PurchasePayload { return { supplierId: props.suppliers[0]?.id ?? '', purchaseDate: currentCanonicalDate(), supplierInvoiceNumber: '', notes: '', discountRial: 0, shippingRial: 0, taxRial: 0, additionalCostsRial: 0 } }
function dateOnly(value: string) { return value.slice(0, 10) }
onMounted(load)
async function load() { loading.value = true; try { rows.value = await purchasesApi.list() } catch (value) { error.value = normalizeError(value).message } finally { loading.value = false } }
function select(value: PurchaseRecord) { selectedId.value = value.id; editing.value = value.status === 'Draft'; form.value = { supplierId: value.supplierId, purchaseDate: dateOnly(value.purchaseDate), supplierInvoiceNumber: value.supplierInvoiceNumber, notes: value.notes, discountRial: value.discountRial, shippingRial: value.shippingRial, taxRial: value.taxRial, additionalCostsRial: value.additionalCostsRial } }
async function create() { if (!props.suppliers.length) { error.value = 'Create a supplier before recording a purchase.'; return }; try { const value = await purchasesApi.create(blank()); rows.value = [value, ...rows.value]; select(value); emit('notify', 'Draft purchase created.') } catch (value) { error.value = String(value) } }
async function save() { if (!current.value) return; try { replace(await purchasesApi.update(current.value.id, form.value)); emit('notify', 'Purchase saved.') } catch (value) { error.value = String(value) } }
async function addItem() { if (!current.value) return; try { replace(await purchasesApi.addItem(current.value.id, item.value)); item.value = { materialId: '', purchaseQuantity: '1', unitAcquisitionCostRial: '0', notes: '' } } catch (value) { error.value = String(value) } }
async function removeItem(id: string) { if (!current.value) return; try { replace(await purchasesApi.removeItem(current.value.id, id)) } catch (value) { error.value = String(value) } }
async function reorder(index: number, direction: number) { if (!current.value) return; const items = [...current.value.items].sort((a, b) => a.position - b.position); const target = index + direction; if (target < 0 || target >= items.length) return; [items[index], items[target]] = [items[target], items[index]]; try { replace(await purchasesApi.reorder(current.value.id, items.map((value) => value.id))) } catch (value) { error.value = String(value) } }
async function post() { if (!current.value || !(await confirmAction({ title: 'Post purchase', message: 'Post this purchase and create inventory movements?', confirmLabel: 'Post purchase' }))) return; try { replace(await purchasesApi.post(current.value.id)); editing.value = false; emit('notify', 'Purchase posted.') } catch (value) { error.value = normalizeError(value).message } }
async function cancel() { if (!current.value || !(await confirmAction({ title: 'Cancel purchase', message: 'Cancel this posted purchase? This creates compensating movements.', confirmLabel: 'Cancel purchase', danger: true }))) return; try { replace(await purchasesApi.cancel(current.value.id)); editing.value = false; emit('notify', 'Purchase cancelled with history preserved.') } catch (value) { error.value = normalizeError(value).message } }
async function removeDraft() { if (!current.value || !(await confirmAction({ title: 'Delete purchase draft', message: 'Delete this draft permanently?', confirmLabel: 'Delete draft', danger: true }))) return; try { await purchasesApi.deleteDraft(current.value.id); rows.value = rows.value.filter((value) => value.id !== current.value!.id); selectedId.value = null; emit('notify', 'Draft deleted.') } catch (value) { error.value = normalizeError(value).message } }
function replace(value: PurchaseRecord) { rows.value = rows.value.map((item) => item.id === value.id ? value : item); selectedId.value = value.id; form.value = { supplierId: value.supplierId, purchaseDate: dateOnly(value.purchaseDate), supplierInvoiceNumber: value.supplierInvoiceNumber, notes: value.notes, discountRial: value.discountRial, shippingRial: value.shippingRial, taxRial: value.taxRial, additionalCostsRial: value.additionalCostsRial } }
</script>

<template>
  <div>
    <WorkspaceStickyStack><header><div><p>Catalog / inventory</p><h1>Purchases</h1><p>Record supplier purchases, then post them into the immutable inventory ledger.</p></div><button class="btn btn-ghost" @click="create"><Plus :size="16" /> New purchase</button></header></WorkspaceStickyStack>
    <div v-if="error" role="alert">{{ error }} <button class="btn btn-ghost" @click="error = ''" aria-label="Dismiss"><X :size="14" /></button></div>
    <section>
      <SectionPanel title="Purchase register" subtitle="Drafts are editable; posted history is protected."><div v-if="loading">Loading purchases…</div><div v-else-if="rows.length"><table class="table table-zebra w-full"><thead><tr><th>Purchase</th><th>Supplier</th><th>Date</th><th>Total</th><th>Paid</th><th>Remaining</th><th>Status</th></tr></thead><tbody><tr v-for="value in rows" :key="value.id" :class="{ 'bg-base-300': selectedId === value.id }" @click="select(value)"><td><span>{{ value.purchaseNumber }}</span><span>{{ value.supplierInvoiceNumber || 'No invoice' }}</span></td><td>{{ value.supplierName }}</td><td>{{ formatDateTime(value.purchaseDate) }}</td><td>{{ formatMoney(value.totalRial, props.currencyUnit) }}</td><td>{{ formatMoney(value.paidRial || 0, props.currencyUnit) }}</td><td>{{ formatMoney(value.remainingRial ?? value.totalRial, props.currencyUnit) }}</td><td><StatusBadge :label="value.status" :tone="value.status === 'Posted' ? 'green' : value.status === 'Cancelled' ? 'slate' : 'amber'" /></td></tr></tbody></table></div><div v-else><ShoppingCart :size="22" /><p>No purchases yet.</p><button class="btn btn-ghost" @click="create"><Plus :size="15" /> Record purchase</button></div></SectionPanel>
      <SectionPanel v-if="current" title="Purchase editor" :subtitle="current.status === 'Draft' ? 'Draft purchase' : 'Historical purchase · read only'"><div><StatusBadge :label="current.status" :tone="current.status === 'Posted' ? 'green' : current.status === 'Cancelled' ? 'slate' : 'amber'" /><span>{{ current.purchaseNumber }}</span></div><form v-if="editing" @submit.prevent="save"><div><label class="form-control gap-1"><span>Supplier</span><SelectField v-model="form.supplierId" label="Supplier" :options="[{ label: 'Select supplier', value: '' }, ...props.suppliers.map((supplier) => ({ label: supplier.name, value: supplier.id }))]" /></label><label class="form-control gap-1"><span>Purchase date</span><JalaliDatePicker v-model="form.purchaseDate" placeholder="Select Jalali date" /></label></div><label class="form-control gap-1"><span>Supplier invoice</span><input class="input input-bordered w-full min-w-0" v-model="form.supplierInvoiceNumber" /></label><div><label class="form-control gap-1"><span>Discount Rial</span><input class="input input-bordered w-full min-w-0" v-model.number="form.discountRial" type="number" min="0" /></label><label class="form-control gap-1"><span>Shipping Rial</span><input class="input input-bordered w-full min-w-0" v-model.number="form.shippingRial" type="number" min="0" /></label><label class="form-control gap-1"><span>Tax Rial</span><input class="input input-bordered w-full min-w-0" v-model.number="form.taxRial" type="number" min="0" /></label><label class="form-control gap-1"><span>Additional Rial</span><input class="input input-bordered w-full min-w-0" v-model.number="form.additionalCostsRial" type="number" min="0" /></label></div><label class="form-control gap-1"><span>Notes</span><textarea class="textarea textarea-bordered w-full min-w-0" v-model="form.notes" rows="2" /></label><button class="btn btn-ghost" type="submit"><Save :size="15" /> Save metadata</button></form><div><h3>Items <span>{{ current.items.length }}</span></h3><div v-for="(line, index) in [...current.items].sort((a, b) => a.position - b.position)" :key="line.id"><div><strong>{{ line.materialName }}</strong><small>{{ line.purchaseQuantity }} {{ line.purchaseUnit }} → {{ line.consumptionQuantity }} {{ line.consumptionUnit }}</small></div><span>{{ formatMoney(line.lineTotalRial, props.currencyUnit) }}</span><span v-if="editing"><button class="btn btn-ghost" :disabled="index === 0" aria-label="Move line up" @click="reorder(index, -1)"><ArrowUp :size="13" /></button><button class="btn btn-ghost" :disabled="index === current.items.length - 1" aria-label="Move line down" @click="reorder(index, 1)"><ArrowDown :size="13" /></button></span><button class="btn btn-ghost" v-if="editing" @click="removeItem(line.id)" aria-label="Remove item"><Trash2 :size="14" /></button></div><form v-if="editing" @submit.prevent="addItem"><SelectField v-model="item.materialId" label="Material" :options="[{ label: 'Material', value: '' }, ...props.materials.map((material) => ({ label: material.name, value: material.id }))]" /><input class="input input-bordered w-full min-w-0" v-model="item.purchaseQuantity" required placeholder="Qty" inputmode="decimal" /><input class="input input-bordered w-full min-w-0" v-model="item.unitAcquisitionCostRial" required placeholder="Unit cost Rial" inputmode="numeric" /><button class="btn btn-ghost"><Plus :size="15" /> Add line</button></form></div><dl><div><dt>Subtotal</dt><dd>{{ formatMoney(current.subtotalRial, props.currencyUnit) }}</dd></div><div><dt>Discount / costs</dt><dd>{{ formatMoney(current.discountRial, props.currencyUnit) }} / {{ formatMoney(current.shippingRial + current.taxRial + current.additionalCostsRial, props.currencyUnit) }}</dd></div><div><dt>Total</dt><dd>{{ formatMoney(current.totalRial, props.currencyUnit) }}</dd></div></dl><div><button class="btn btn-ghost" v-if="current.status === 'Draft'" @click="post"><Check :size="15" /> Post purchase</button><button class="btn btn-ghost" v-if="current.status === 'Draft'" @click="removeDraft"><Trash2 :size="15" /> Delete draft</button><button class="btn btn-ghost" v-if="current.status === 'Posted'" @click="cancel">Cancel / reverse</button></div></SectionPanel>
      <SectionPanel v-else title="Purchase inspector" subtitle="Select a purchase or start a new draft."><div><ShoppingCart :size="20" /><p>Purchase details will appear here.</p></div></SectionPanel>
    </section>
  </div>
</template>
